T.openCommand=()=>{T.openModal('A quicker way to find your focus.',`<input id="command-search" class="command-input" aria-label="Search your workspace" placeholder="Search tasks, projects, or pages…" data-input="command" autocomplete="off"><div id="command-results">${T.commandResults('')}</div>`,true);setTimeout(()=>$('#command-search')?.focus(),25)};
T.commandResults=q=>{q=q.trim().toLowerCase();let tasks=q?T.tasks('all').filter(t=>t.title.toLowerCase().includes(q)).slice(0,7):[],ps=q?T.projects('all').filter(p=>p.name.toLowerCase().includes(q)).slice(0,4):[],nav=menuItems.filter(i=>T.permission(i[0])&&(!q||i[2].toLowerCase().includes(q))).slice(0,q?4:8);let result=(icon,title,sub,action,id)=>`<button class="command-result" data-action="${action}" data-id="${id}"><span class="metric-icon">${I(icon)}</span><span><h3>${E(title)}</h3><p>${E(sub)}</p></span><span class="spacer"></span>${I('arrowUp','sm')}</button>`;return `${tasks.length?'<div class="command-group">TASKS</div>'+tasks.map(t=>result('checkSquare',t.title,T.project(t.project).name+(T.isPersonal(t)?' · Private':''),'search-task',t.id)).join(''):''}${ps.length?'<div class="command-group">PROJECTS</div>'+ps.map(p=>result(p.icon,p.name,p.department,'project-open',p.id)).join(''):''}${nav.length?'<div class="command-group">JUMP TO</div>'+nav.map(i=>result(i[1],i[2],'Open workspace page','nav',i[0])).join(''):''}${!tasks.length&&!ps.length&&!nav.length?C.empty('No matching results','Try a shorter phrase or a project name.'):''}`};
T.openWorkspace=()=>T.openModal('A place for every kind of work.',`<p style="margin-bottom:18px">Choose an organization. Your private work always stays separate.</p>${T.db.orgs.map(o=>`<button class="workspace-choice ${o.id===T.activeOrg()?'active':''}" data-action="workspace-switch" data-id="${o.id}"><span class="workspace-icon">${E(o.short)}</span><span><h3>${E(o.name)}</h3><p class="tiny muted">Fictional enterprise workspace</p></span><span class="spacer"></span>${o.id===T.activeOrg()?I('check'):I('arrowUp')}</button>`).join('')}<button class="workspace-choice" data-action="nav" data-id="personal"><span class="workspace-icon">${I('lock')}</span><span><h3>Your personal workspace</h3><p class="tiny muted">Private projects, goals & notes</p></span><span class="spacer"></span>${I('arrowUp')}</button>`);
T.openProfile=()=>T.openModal('Explore your workspace.',`<div class="row" style="margin-bottom:22px">${C.avatar('u1','lg')}<div><h3>${E(T.me().name)}</h3><p>${E(T.me().title)}</p></div></div>${C.notice('Role preview illustrates the blueprint. It is not authentication or a server authorization boundary.')}<form data-form="role"><div class="form-grid">${C.field('Preview as','role','text',T.db.session.role,T.ROLES,true)}</div><div class="modal-actions">${C.btn('My settings','profile-settings','settings')}<button class="btn primary">Apply role preview</button></div></form>`);
T.openTeam=(id,edit=false)=>{let team=T.db.teams.find(t=>t.id===id);if(!team)return;if(edit)return T.teamForm(id);T.openModal(team.name,`<p>${E(team.department)} · Led by ${E(T.user(team.lead).name)}</p>${team.members.map(uid=>`<div class="settings-row"><div class="row">${C.avatar(uid)}<div><h3>${E(T.user(uid).name)}</h3><p>${E(T.user(uid).title)}</p></div></div>${C.iconbtn('Remove member','team-member-remove','close',{id,member:uid})}</div>`).join('')}<form data-form="team-add-member" data-id="${id}" style="margin-top:20px"><div class="row"><select name="member" aria-label="Add member to team" style="flex:1">${T.db.users.filter(u=>!team.members.includes(u.id)).map(u=>`<option value="${u.id}">${E(u.name)}</option>`).join('')}</select><button class="btn soft">Add member</button></div></form>`)};
T.teamForm=id=>{let team=T.db.teams.find(t=>t.id===id)||{name:'',department:'Engineering',lead:'u2'};T.openModal(id?'Edit team':'A team for the next chapter.',T.form('team',C.field('Team name','name','text',team.name,null,true,'required maxlength="100"')+C.field('Department','department','text',team.department,['Engineering','Product','Security','Design','Marketing','People'])+C.field('Team lead','lead','text',team.lead,T.db.users.map(u=>[u.id,u.name])),id?'Save team':'Create team',id||''))};
T.ruleForm=id=>{let r=T.db.rules.find(r=>r.id===id)||{name:'',trigger:'Overdue task',action:'Notify project owner'};T.openModal(id?'Refine your workflow':'Make the next step automatic.',T.form('rule',C.field('Rule name','name','text',r.name,null,true,'required maxlength="100"')+C.field('When this happens','trigger','text',r.trigger,['Overdue task','Blocked task','High priority task'])+C.field('Then do this','action','text',r.action,['Notify project owner','Notify team lead','Add to alert inbox']),id?'Save rule':'Create rule',id||'','This rule evaluates local demo tasks when you run a simulation. No external action will occur.'))};
T.candidate=id=>{let c=T.db.candidates.find(c=>c.id===id&&c.org===T.activeOrg());if(!c)return;T.openModal(c.name,`<p>${E(c.role)} · Fictional candidate profile</p><div class="row" style="margin:18px 0">${c.skills.map(s=>C.badge(s,'gray')).join('')}</div><form data-form="candidate" data-id="${id}"><div class="form-grid">${C.field('Interview stage','stage','text',c.stage,['Screening','Technical interview','Manager review','Offer','Hired','Not selected'],true)}${C.field('Internal feedback','note','textarea','',null,true,'maxlength="1000"')}</div><div class="modal-actions"><button class="btn primary">Save feedback</button></div></form>${c.notes.map(n=>`<div class="notice" style="margin-top:12px">${E(n)}</div>`).join('')}`)};
T.integration=id=>{let names={microsoft:'Microsoft 365',google:'Google Workspace',slack:'Slack',jira:'Jira',github:'GitHub',webhooks:'Custom webhooks'},connected=T.db.integrations.find(c=>c.org===T.activeOrg()&&c.provider===id);T.openModal(names[id]||'Integration',C.notice('Configuration preview only. No OAuth consent, account access, or network connection is performed.')+`<div class="settings-row"><h3>Preview state</h3>${C.badge(connected?'Connected · demo':'Not connected',connected?'green':'gray')}</div><div class="settings-row"><h3>Scope</h3><span class="tiny muted">Read authorized workspace data</span></div><div class="settings-row"><h3>Workspace</h3><span class="tiny muted">${E(T.org().name)}</span></div><div class="modal-actions">${C.btn(connected?'Disconnect demo':'Enable demo state','integration-toggle',connected?'close':'link',connected?'':'primary',{id})}</div>`)};
T.ask=q=>{let question=q.trim().slice(0,300);if(!question)return;let low=question.toLowerCase(),ts,answer,scope='Current organization',method;if(/block|depend/.test(low)){ts=T.tasks().filter(t=>t.status==='Blocked');answer=`${ts.length} company tasks are blocked. Review the dependency with the accountable owner before changing delivery commitments.`;method='status = Blocked'}else if(/priorit|focus|my |today/.test(low)){ts=T.tasks('mine').filter(t=>!T.isTerminal(t)).sort((a,b)=>T.PRIORITIES.indexOf(a.priority)-T.PRIORITIES.indexOf(b.priority)||a.due.localeCompare(b.due)).slice(0,5);answer='Start with these assigned priorities. Urgent and high priority work appears first, then earlier deadlines. Review your calendar before taking on another commitment.';scope='Your assigned work, including private tasks';method='Nonterminal, owned by you; priority then due date'}else if(/summary|summari|portfolio|project|work|attention|risk/.test(low)){ts=T.tasks().filter(t=>t.status==='Blocked'||T.overdue(t));let m=T.metrics(T.tasks());answer=`Your portfolio has ${T.projects().length} projects and ${m.total} eligible tasks. ${m.done} are complete (${m.rate}%). ${m.attention} tasks need attention based on blocked or overdue status. This is a record summary, not a forecast.`;method='Company-only task counts; union of blocked and overdue'}else{ts=[];answer='I can summarize the demo portfolio, list blocked tasks, or show your priorities. This demo uses local rules and cannot answer unrelated questions or infer delivery forecasts.';method='Unsupported question; no model inference'}T.ui.aiHistory.push({question,answer,tasks:ts.map(t=>t.id),scope,method});T.log('Reviewed a rules-based work briefing');T.persist();T.render()};
