T.exportCSV=()=>{let base=T.ui.route.split('/')[0],ts=['dashboard','work','calendar','board','personal'].includes(base)?base==='personal'?T.tasks('personal'):base==='work'?T.ui.currentTasks:T.tasks('mine'):base==='project'?T.projectTasks(T.ui.route.split('/')[1]):T.tasks();if(base==='reports')ts=ts.filter(T.inPeriod).filter(t=>T.ui.reportDept==='All departments'||T.project(t.project).department===T.ui.reportDept);let safe=v=>{let s=String(v??'');if(/^[\s]*[=+@\-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'},rows=[['ID','Title','Project','Workspace','Owner','Status','Priority','Start','Due','Estimate hours'],...ts.map(t=>['TF-'+t.number,t.title,T.project(t.project).name,T.isPersonal(t)?'Private personal':T.org().name,T.user(t.owner).name,t.status,t.priority,t.start,t.due,t.hours])],name='TaskForce_'+base+'_'+T.today()+'.csv';T.download(name,'\ufeff'+rows.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8');T.db.exports.unshift({id:T.id('ex'),org:T.activeOrg(),name,date:new Date().toISOString(),count:ts.length,scope:['executive','reports','projects','teams'].includes(base)?'Company only':'Current visible work'});T.log('Exported '+ts.length+' task records');T.persist();T.render();T.toast('CSV downloaded · '+ts.length+' records')};
